import{_ as o,a0 as s,w as u,s as a,I as m,x as d,a1 as r,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"DNF 和 Yum 的區別，為什麼 Yum 會被 DNF 取代？ | LCTT x X-CMD","titleTemplate":false,"description":"DNF 和 Yum 的區別，為什麼 Yum 會被 DNF 取代？ | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DNF 和 Yum 的區別，為什麼 Yum 會被 DNF 取代？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DNF 和 Yum 的區別，為什麼 Yum 會被 DNF 取代？ | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20191220 The Difference Between DNF and YUM, Why is Yum Replaced by DNF","title":"DNF 和 Yum 的區別，為什麼 Yum 會被 DNF 取代？","tag":"202004","desc":""},"relativePath":"202004/20191220 The Difference Between DNF and YUM, Why is Yum Replaced by DNF.md","filePath":"[post].md"}'),p={name:"202004/20191220 The Difference Between DNF and YUM, Why is Yum Replaced by DNF.md"};function i(f,t,D,Y,N,F){const e=s("Link");return u(),a("div",null,[t[20]||(t[20]=m("h1",{id:"dnf-和-yum-的區別-為什麼-yum-會被-dnf-取代",tabindex:"-1"},[d("DNF 和 Yum 的區別，為什麼 Yum 會被 DNF 取代？ "),m("a",{class:"header-anchor",href:"#dnf-和-yum-的區別-為什麼-yum-會被-dnf-取代","aria-label":"Permalink to “DNF 和 Yum 的區別，為什麼 Yum 會被 DNF 取代？”"},"​")],-1)),m("p",null,[t[2]||(t[2]=d("由於 Yum 中許多長期存在的問題仍未得到解決，因此 ",-1)),r(e,{href:"https://www.2daygeek.com/yum-command-examples-manage-packages-rhel-centos-systems/"},{default:n(()=>[...t[0]||(t[0]=[d("Yum 包管理器",-1)])]),_:1}),t[3]||(t[3]=d("已被 ",-1)),r(e,{href:"https://www.2daygeek.com/linux-dnf-command-examples-manage-packages-fedora-centos-rhel-systems/"},{default:n(()=>[...t[1]||(t[1]=[d("DNF 包管理器",-1)])]),_:1}),t[4]||(t[4]=d("取代。這些問題包括性能差、內存佔用過多、依賴解析速度變慢等。",-1))]),t[21]||(t[21]=l('<p>DNF 使用 <code>libsolv</code> 進行依賴解析，由 SUSE 開發和維護，旨在提高性能。</p><p>Yum 主要是用 Python 編寫的，它有自己的應對依賴解析的方法。它的 API 沒有完整的文檔，它的擴展系統只允許 Python 插件。</p><p>Yum 是 RPM 的前端工具，它管理依賴關係和資源庫，然後使用 RPM 來安裝、下載和刪除包。</p><p>為什麼他們要建立一個新的工具，而不是修復現有的問題呢？</p><p>Ales Kozamblak 解釋説，這個修復在技術上是不可行的，而且 Yum 團隊還沒有準備好立即接受修改。</p><p>另外，最大的挑戰是，Yum 有 56000 行代碼，但 DNF 只有 29000 行代碼。</p><p>所以除了分叉，沒有辦法解決。</p><p>不過 Yum 的運行情況還算可以。</p><div class="table-wrap"><table><thead><tr><th>編號</th><th>DNF（Dandified YUM）</th><th>YUM（Yellowdog Updater, Modified）</th></tr></thead><tbody><tr><td>1</td><td>DNF 使用 libsolv 來解析依賴關係，由 SUSE 開發和維護</td><td>YUM 使用公開的 API 來解析依賴關係</td></tr><tr><td>2</td><td>API 有完整的文檔</td><td>API 沒有完整的文檔</td></tr><tr><td>3</td><td>由 C、C++、Python 編寫的</td><td>只用 Python 編寫</td></tr><tr><td>4</td><td>DNF 目前在 Fedora、RHEL 8、CentOS 8、OEL 8 和 Mageia 6/7 中使用</td><td>YUM 目前在 RHEL 6/7、CentOS 6/7、OEL 6/7 中使用</td></tr><tr><td>5</td><td>DNF 支持各種擴展</td><td>Yum 只支持基於 Python 的擴展</td></tr><tr><td>6</td><td>API 有良好的文檔，因此很容易創建新的功能</td><td>因為 API 沒有正確的文檔化，所以創建新功能非常困難</td></tr><tr><td>7</td><td>DNF 在同步存儲庫的元數據時，使用的內存較少</td><td>在同步存儲庫的元數據時，YUM 使用了過多的內存</td></tr><tr><td>8</td><td>DNF 使用滿足性算法來解決依賴關係解析（它是用字典的方法來存儲和檢索包和依賴信息）</td><td>由於使用公開 API 的原因，Yum 依賴性解析變得遲鈍</td></tr><tr><td>9</td><td>從內存使用量和版本庫元數據的依賴性解析來看，性能都不錯</td><td>總的來説，在很多因素的影響下，表現不佳</td></tr><tr><td>10</td><td>DNF 更新：在 DNF 更新過程中，如果包中包含不相關的依賴，則不會更新</td><td>YUM 將在沒有驗證的情況下更新軟件包</td></tr><tr><td>11</td><td>如果啓用的存儲庫沒有響應，DNF 將跳過它，並繼續使用可用的存儲庫處理事務</td><td>如果有存儲庫不可用，YUM 會立即停止</td></tr><tr><td>12</td><td><code>dnf update</code> 和 <code>dnf upgrade</code> 是等價的</td><td>在 Yum 中則不同</td></tr><tr><td>13</td><td>安裝包的依賴關係不更新</td><td>Yum 為這種行為提供了一個選項</td></tr><tr><td>14</td><td>清理刪除的包：當刪除一個包時，DNF 會自動刪除任何沒有被用户明確安裝的依賴包</td><td>Yum 不會這樣做</td></tr><tr><td>15</td><td>存儲庫緩存更新計劃：默認情況下，系統啓動後 10 分鐘後，DNF 每小時會對配置的存儲庫檢查一次更新。這個動作由系統定時器單元 <code>dnf-makecache.timer</code> 控制</td><td>Yum 也會這樣做</td></tr><tr><td>16</td><td>內核包不受 DNF 保護。不像 Yum，你可以刪除所有的內核包，包括運行中的內核包</td><td>Yum 不允許你刪除運行中的內核</td></tr><tr><td>17</td><td>libsolv：用於解包和讀取資源庫。hawkey: 為 libsolv 提供簡化的 C 和 Python API 庫。librepo: 提供 C 和 Python（類似 libcURL）API 的庫，用於下載 Linux 存儲庫元數據和軟件包。libcomps: 是 yum.comps 庫的替代品。它是用純 C 語言編寫的庫，有 Python 2 和 Python 3 的綁定。</td><td>Yum 不使用單獨的庫來執行這些功能</td></tr><tr><td>18</td><td>DNF 包含 29000 行代碼</td><td>Yum 包含 56000 行代碼</td></tr><tr><td>19</td><td>DNF 由 Ales Kozumplik 開發</td><td>YUM 由 Zdenek Pavlas、Jan Silhan 和團隊成員開發</td></tr></tbody></table></div><hr>',10)),m("p",null,[t[6]||(t[6]=d("via: ",-1)),r(e,{href:"https://www.2daygeek.com/comparison-difference-between-dnf-vs-yum/"},{default:n(()=>[...t[5]||(t[5]=[d("https://www.2daygeek.com/comparison-difference-between-dnf-vs-yum/",-1)])]),_:1})]),m("p",null,[t[11]||(t[11]=d("作者：",-1)),r(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...t[7]||(t[7]=[d("Magesh Maruthamuthu",-1)])]),_:1}),t[12]||(t[12]=d(" 選題：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[8]||(t[8]=[d("lujun9972",-1)])]),_:1}),t[13]||(t[13]=d(" 譯者：",-1)),r(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[d("wxy",-1)])]),_:1}),t[14]||(t[14]=d(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[10]||(t[10]=[d("wxy",-1)])]),_:1})]),m("p",null,[t[17]||(t[17]=d("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[15]||(t[15]=[d("LCTT",-1)])]),_:1}),t[18]||(t[18]=d(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:n(()=>[...t[16]||(t[16]=[d("Linux中國",-1)])]),_:1}),t[19]||(t[19]=d(" 榮譽推出",-1))])])}const T=o(p,[["render",i]]);export{P as __pageData,T as default};
